package com.markethub.vendor.store.api;
import com.markethub.vendor.application.ApprovedVendorAccess; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.UUID;
@Service public class StoreProfileService {
 private final JdbcTemplate jdbc; private final ApprovedVendorAccess access; public StoreProfileService(JdbcTemplate jdbc,ApprovedVendorAccess access){this.jdbc=jdbc;this.access=access;}
 public record StoreView(UUID id,UUID vendorId,String storeName,String slug,String description,String logoUrl,String supportEmail,String supportPhone,Instant createdAt,Instant updatedAt){}
 public StoreView get(UUID userId){return find(access.requireApprovedVendor(userId));}
 @Transactional public StoreView create(UUID userId,StoreProfileRequest r){UUID vendor=access.requireApprovedVendor(userId);if(exists(vendor))throw new IllegalStateException("A store profile already exists");UUID id=UUID.randomUUID();jdbc.update("insert into store_profiles(id,vendor_id,store_name,slug,description,logo_url,support_email,support_phone) values (?,?,?,?,?,?,?,?)",id,vendor,r.storeName().trim(),r.slug(),r.description(),r.logoUrl(),r.supportEmail(),r.supportPhone());return find(vendor);}
 @Transactional public StoreView update(UUID userId,StoreProfileRequest r){UUID vendor=access.requireApprovedVendor(userId);if(!exists(vendor))throw new IllegalArgumentException("Create a store profile before updating it");jdbc.update("update store_profiles set store_name=?,slug=?,description=?,logo_url=?,support_email=?,support_phone=?,updated_at=now(),version=version+1 where vendor_id=?",r.storeName().trim(),r.slug(),r.description(),r.logoUrl(),r.supportEmail(),r.supportPhone(),vendor);return find(vendor);}
 private boolean exists(UUID vendor){Integer n=jdbc.queryForObject("select count(*) from store_profiles where vendor_id=?",Integer.class,vendor);return n!=null&&n>0;}
 private StoreView find(UUID vendor){return jdbc.query("select id,vendor_id,store_name,slug,description,logo_url,support_email,support_phone,created_at,updated_at from store_profiles where vendor_id=?",(rs,n)->new StoreView(rs.getObject("id",UUID.class),rs.getObject("vendor_id",UUID.class),rs.getString("store_name"),rs.getString("slug"),rs.getString("description"),rs.getString("logo_url"),rs.getString("support_email"),rs.getString("support_phone"),rs.getTimestamp("created_at").toInstant(),rs.getTimestamp("updated_at").toInstant()),vendor).stream().findFirst().orElseThrow(()->new IllegalArgumentException("Store profile not found"));}
}